import { greet } from './index.js';

const usage = 'Usage: greenfield-proof [name]\n       greenfield-proof --help';
const args = process.argv.slice(2);

if (args.length === 1 && args[0] === '--help') {
  console.log(usage);
} else if (args.length > 1 || args.some((arg) => arg.startsWith('-'))) {
  console.error(usage);
  process.exitCode = 1;
} else {
